using System; // Reject malformed notes and check detached array ownership.
using System.IO; // Compare independently generated prior-release traces.
using Outbreak.Contracts; // Inspect personal last-seen information rather than hidden current stocks.
using Outbreak.Core; // Exercise actual observations, remembered routes and searches.
using Outbreak.Persistence; // Verify complete deterministic continuation.
public static partial class Program
{
    private static int RememberedFood(ActorState actor,int x,int y) { if(actor.shelfMemory!=null)foreach(ShelfMemoryRecord note in actor.shelfMemory)if(note.x==x && note.y==y)return note.food;return -2; }
    private static void CheckShelfMemoryCases()
    {
        Check("Actual searches persist empty and stocked shelf notes across later hunger", () => {
            World w=EncounterScenarios.ShelfMemoryTest();Require(w.ShelfMemoryEnabled && w.Tick==26 && RememberedFood(w.ActorAt(0),2,3)==0 && RememberedFood(w.ActorAt(0),7,4)==3,"Earlier searches did not retain personal stock knowledge.");Run(w,10);Require(w.ActorAt(0).foodX==7 && w.ActorAt(0).foodY==4 && w.ActorAt(0).x==4 && w.TerrainAt(5,4)==Terrain.DoorClosed,"Forager failed to head toward supplies remembered beyond a closed door.");Run(w,40);Require(w.ActorAt(0).carriedFood==2 && w.ActorAt(0).hunger<40 && RememberedFood(w.ActorAt(0),2,3)==0 && RememberedFood(w.ActorAt(0),7,4)==0,"Searching and eating lost notes or failed to mark the depleted source empty.");Inspect(w);
        });
        Check("Hidden stock changes do not update memory until the human sees the shelf again", () => {
            World full=EncounterScenarios.ShelfMemoryTest();SaveDocument s=full.Capture();WorldMap map=WorldMap.Restore(s.map);map.SetShelf(7,4,0,true);s.map=map.Capture();World empty=World.Restore(s);for(int i=0;i<19;i++){full.Step();empty.Step();Require(Documents.Encode(full.ActorAt(0))==Documents.Encode(empty.ActorAt(0)) && full.Capture().randomState==empty.Capture().randomState,"Hidden depletion changed a remembered route before personal observation.");}full.Step();empty.Step();Require(RememberedFood(full.ActorAt(0),7,4)==3 && RememberedFood(empty.ActorAt(0),7,4)==0 && empty.ActorAt(0).foodUntilTick==0,"New sight did not correct stale supply knowledge or stop the empty trip.");
        });
        Check("Confirmed remembered supplies take priority over a closer unsearched shelf", () => {
            SaveDocument s=EncounterScenarios.ShelfMemoryTest().Capture();WorldMap map=WorldMap.Restore(s.map);map.SetShelf(1,4,6);s.map=map.Capture();World w=World.Restore(s);Run(w,5);Require(w.ActorAt(0).foodX==7 && w.ActorAt(0).foodY==4 && w.ActorAt(0).carriedFood==0 && !w.ShelfAt(1,4).searched,"Closer unknown furniture displaced remembered food or was searched remotely.");
        });
        Check("Personal notes learn unopened locations without revealing hidden contents", () => {
            WorldMap a=new WorldMap(12,8);a.SetShelf(4,2,6);WorldMap b=WorldMap.Restore(a.Capture());b.SetShelf(4,2,0);World left=new World(a,214,encounter:true,hunger:true,carefulSearch:false),right=new World(b,214,encounter:true,hunger:true,carefulSearch:false);int id;left.TrySpawn(Species.Human,2,2,out id);right.TrySpawn(Species.Human,2,2,out id);left.Step();right.Step();Require(RememberedFood(left.ActorAt(0),4,2)==-1 && Documents.Encode(left.ActorAt(0))==Documents.Encode(right.ActorAt(0)),"Fed observer learned unopened contents or ignored nearby shelf locations.");
        });
        Check("An empty note refreshes when exposed food is personally seen again", () => {
            SaveDocument s=EncounterScenarios.ShelfMemoryTest().Capture();s.actors[0].x=6;s.actors[0].y=4;s.actors[0].hunger=0;WorldMap map=WorldMap.Restore(s.map);map.SetShelf(7,4,0,true);s.map=map.Capture();World w=World.Restore(s);Run(w,5);Require(RememberedFood(w.ActorAt(0),7,4)==0,"Visible emptiness did not replace old stock.");s=w.Capture();s.actors[0].x=6;s.actors[0].y=4;map=WorldMap.Restore(s.map);map.SetShelf(7,4,5,true);s.map=map.Capture();w=World.Restore(s);Run(w,5);Require(RememberedFood(w.ActorAt(0),7,4)==5 && w.ActorAt(0).carriedFood==0,"A visible restock stayed permanently empty or granted remote food.");
        });
        Check("Shelf notes expire exactly between actor opportunities without automatic remote refresh", () => {
            SaveDocument s=EncounterScenarios.ShelfMemoryTest().Capture();s.tick=3599;s.actors[0].hunger=0;for(int i=0;i<s.actors[0].shelfMemory.Length;i++)s.actors[0].shelfMemory[i].observedTick=0;World w=World.Restore(s);Require(w.ActorAt(0).shelfMemory.Length==2,"Valid old notes expired early.");w.Step();Require(w.ActorAt(0).shelfMemory==null && w.Tick==3600,"Stale observations did not clear at their exact deadline.");
        });
        Check("Memory remains bounded and deterministic after different shelf insertion orders", () => {
            int[,] cells={{6,6},{8,6},{10,6},{12,6},{14,6},{6,8},{8,8},{12,8},{14,8},{6,10},{14,10},{8,12},{10,12},{12,12},{6,14},{14,14}};World a=new World(new WorldMap(20,20),214,encounter:true,hunger:true,carefulSearch:false),b=new World(new WorldMap(20,20),214,encounter:true,hunger:true,carefulSearch:false);int id;a.TrySpawn(Species.Human,10,10,out id);b.TrySpawn(Species.Human,10,10,out id);for(int i=0;i<cells.GetLength(0);i++){Require(a.TryPlaceShelf(cells[i,0],cells[i,1],6),"Forward furniture setup failed.");int j=cells.GetLength(0)-1-i;Require(b.TryPlaceShelf(cells[j,0],cells[j,1],6),"Reverse furniture setup failed.");}a.Step();b.Step();Require(a.ActorAt(0).shelfMemory.Length==8 && State(a)==State(b),"Memory overflowed or insertion order changed retained knowledge.");World restored=Documents.ParseSave(State(a));for(int i=0;i<50;i++){a.Step();b.Step();restored.Step();Require(State(a)==State(b) && State(a)==State(restored) && a.ActorAt(0).shelfMemory.Length<=8,"Bounded notes changed after continuation or canonical map reload.");}
        });
        Check("Another human's observations do not automatically appear in a hidden observer's notebook", () => {
            SaveDocument s=EncounterScenarios.ShelfMemoryTest().Capture();s.actors[0].shelfMemory=null;s.actors[0].hunger=0;s.actors[0].x=6;s.actors[0].y=4;World w=World.Restore(s);int id;w.TrySpawn(Species.Human,2,4,out id);Run(w,6);Require(RememberedFood(w.ActorAt(0),7,4)==3 && RememberedFood(w.ActorAt(1),7,4)==-2,"One person's discovery granted knowledge through the closed partition.");
        });
        Check("Actor reads, captures and restores never expose mutable live memory arrays", () => {
            World w=EncounterScenarios.ShelfMemoryTest();ActorState copy=w.ActorAt(0);copy.shelfMemory[0].food=999;Require(RememberedFood(w.ActorAt(0),2,3)==0,"ActorAt exposed its live notebook.");SaveDocument captured=w.Capture();captured.actors[0].shelfMemory[0].food=998;Require(RememberedFood(w.ActorAt(0),2,3)==0,"Capture exposed its live notebook.");captured=w.Capture();World restored=World.Restore(captured);captured.actors[0].shelfMemory[0].food=997;Require(RememberedFood(restored.ActorAt(0),2,3)==0,"Restore retained a caller-owned array.");captured=w.Capture();long observed=captured.actors[0].shelfMemory[0].observedTick;Run(w,5);Require(captured.actors[0].shelfMemory[0].observedTick==observed,"Later observations mutated an earlier snapshot.");
        });
        Check("Remembered supplies beyond one local route query remain reachable using bounded waypoints", () => {
            WorldMap map=new WorldMap(50,8);map.SetShelf(35,4,6,true);World w=new World(map,214,encounter:true,hunger:true,carefulSearch:false);int id;w.TrySpawn(Species.Human,2,4,out id);SaveDocument s=w.Capture();s.actors[0].hunger=80;s.actors[0].bravery=3;s.actors[0].shelfMemory=new[]{new ShelfMemoryRecord{x=35,y=4,food=6,observedTick=0}};w=World.Restore(s);Run(w,20);Require(w.ActorAt(0).x>=6 && w.ActorAt(0).foodX==35,"Out-of-range memory did not guide local progress.");Run(w,170);Require(w.ShelfAt(35,4).food==3 && w.ActorAt(0).carriedFood==2,"Long remembered trip never reached and searched its known source.");Inspect(w);
        });
        Check("Notebook validation rejects unsupported, duplicate, stale and impossible records", () => {
            World w=EncounterScenarios.ShelfMemoryTest();SaveDocument s=w.Capture();s.rulesVersion=EncounterRules.SharingVersion;Reject(()=>World.Restore(s));s=w.Capture();s.actors[0].shelfMemory[0].food=-2;Reject(()=>World.Restore(s));s=w.Capture();s.actors[0].shelfMemory[0].food=1001;Reject(()=>World.Restore(s));s=w.Capture();s.actors[0].shelfMemory[0].observedTick=s.tick+1;Reject(()=>World.Restore(s));s=w.Capture();s.actors[0].shelfMemory[0].observedTick=-1;Reject(()=>World.Restore(s));s=w.Capture();s.actors[0].shelfMemory[1]=s.actors[0].shelfMemory[0];Reject(()=>World.Restore(s));s=w.Capture();Array.Reverse(s.actors[0].shelfMemory);Reject(()=>World.Restore(s));s=w.Capture();s.actors[0].shelfMemory=new ShelfMemoryRecord[0];Reject(()=>World.Restore(s));s=w.Capture();s.actors[0].shelfMemory=new ShelfMemoryRecord[9];Reject(()=>World.Restore(s));s=w.Capture();s.tick=4000;s.actors[0].shelfMemory[0].observedTick=0;Reject(()=>World.Restore(s));
        });
        Check("Notebook continuation pauses exactly and turning clears personal shelf knowledge", () => {
            World w=EncounterScenarios.ShelfMemoryTest();string before=State(w);new TickClock().Advance(100,w.Step);Require(State(w)==before,"Pause advanced notebook age.");World restored=Documents.ParseSave(before);for(int i=0;i<100;i++){w.Step();restored.Step();Require(State(w)==State(restored),"Personal notebook or revisited supply stock diverged after loading.");}w=EncounterScenarios.ShelfMemoryTest();SaveDocument s=w.Capture();s.actors[0].turnAtTick=s.tick+1;w=World.Restore(s);w.Step();Require(w.ActorAt(0).species==Species.Zombie && w.ActorAt(0).shelfMemory==null,"Turning retained a human notebook.");Inspect(w);
        });
        Check("Prototype-nineteen saves retain independent single-target food behavior", () => {
            string folder=Path.Combine(AppContext.BaseDirectory,"Fixtures");World w=Documents.ParseSave(File.ReadAllText(Path.Combine(folder,"encounter-v19-input.json")));Require(w.FoodSharing && !w.ShelfMemoryEnabled,"Older run silently gained persistent shelf notes.");Run(w,150);Require(State(w)==State(Documents.ParseSave(File.ReadAllText(Path.Combine(folder,"encounter-v19-expected.json")))),"Earlier food target continuation changed.");
        });
    }
}
